package liveassignments;

public class Porgram_Value {
	
	static void decrease(int data)
	{
		data = data-10;
		System.out.println(data);
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int num1 = 100;
		decrease(num1);
		System.out.println("Number : " + num1);

	}

}
